for p in F.t["profiles"]: p["must_change_password"] = False
import build_web
site = tempfile.mkdtemp(); ver = build_web.build(site)
class Q(http.server.SimpleHTTPRequestHandler):
    def log_message(s, *a): pass
srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), functools.partial(Q, directory=site)); port = srv.server_address[1]
threading.Thread(target=srv.serve_forever, daemon=True).start()
from playwright.sync_api import sync_playwright
ok = fail = 0
def check(l, c):
    global ok, fail
    if c: ok += 1; print("  PASS", l)
    else: fail += 1; print("  FAIL", l)
def lead(i, status="none", hours="", **kw):
    r = dict(id=f"p{i}", name=f"Business {i}", phone=f"+1-519-555-010{i}", owner_name="N/A", email="N/A", rating="4.5", reviews=str(100 - i), website="N/A", address="1 Main St",
             search="roofers | Kitchener", btype="Roofing", hours=hours, status=status, notes="", enriched=False, added_at="2026-11-07T14:00:00+00:00",
             called_at=None, meeting_at=None, version=1, updated_at=F.now(), created_at=F.now(), phone_key=f"519555010{i}"); r.update(kw); F.t["leads"].append(r)
alld = json.dumps({d: "9 am-5 pm" for d in ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]})
for i in range(1, 7): lead(i, hours=alld if i < 4 else "")
lead(7, "yellow", called_at="2026-11-06T15:00:00+00:00", btype="Plumbing"); lead(8, "green", called_at="2026-11-06T16:00:00+00:00", meeting_at="2026-11-12T19:00:00+00:00", btype="Plumbing")
F.t["deals"].append(dict(id="d0000000-0000-4000-8000-000000000001", client="Old Client", upfront=500, monthly=100, months=6, closed_at="2026-11-01", first_bill="2026-12-01", notes="", owner_id=ids["james"], version=1, updated_at=F.now(), created_at=F.now()))
F.t["notes"].append(dict(id="a0000000-0000-4000-8000-000000000001", kind="script", scope="shared", owner_id=ids["james"], title="Team opener", folder="", body="<p>Hello <b>there</b></p>", version=1, updated_at=F.now(), created_at=F.now()))
F.t["notes"].append(dict(id="a0000000-0000-4000-8000-000000000002", kind="note", scope="personal", owner_id=ids["james"], title="James private", folder="", body="secret", version=1, updated_at=F.now(), created_at=F.now()))
F.t["settings"].append(dict(key="daily_targets", value={"calls": 100, "connections": 20, "meetings": 3, "sales": 1}))
errs = []
def A(pg, name, *args): return pg.evaluate("([n,a])=>window.LF_API(n,...a)", [name, list(args)])
def login(pg, user, pw):
    pg.fill("#lgUser", user); pg.fill("#lgPass", pw); pg.click("#lgGo"); pg.wait_for_selector("#login.on", state="detached", timeout=8000)
    pg.wait_for_function("document.querySelector('#syncTx').textContent==='Synced'", timeout=15000)
